-- =============================================================
-- AGRO-SHIELD
-- Migration 008: Notifications System
--
-- Stores user notifications generated by different Agro-Shield
-- features.
--
-- Possible notification sources include:
--   - Orders
--   - Payments
--   - Marketplace
--   - Messages
--   - Learning / Training
--   - Events
--   - Announcements
--   - System events
--
-- Notifications are an information layer.
--
-- They do NOT replace the actual records in:
--   orders
--   products
--   negotiations
--   messages
--   events
--   announcements
--   learning tables
-- =============================================================


-- =============================================================
-- NOTIFICATIONS
-- =============================================================

CREATE TABLE IF NOT EXISTS notifications (

    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    -- =========================================================
    -- Recipient
    -- =========================================================
    user_id INTEGER NOT NULL,

    -- =========================================================
    -- Notification Type
    -- =========================================================
    notification_type TEXT NOT NULL,

    -- =========================================================
    -- Notification Content
    -- =========================================================
    title TEXT NOT NULL,

    message TEXT NOT NULL,

    -- =========================================================
    -- Optional Reference
    --
    -- Examples:
    --
    -- reference_type = 'order'
    -- reference_id   = 123
    --
    -- reference_type = 'product'
    -- reference_id   = 456
    --
    -- reference_type = 'event'
    -- reference_id   = 789
    --
    -- This is intentionally polymorphic because notifications
    -- can originate from many different Agro-Shield modules.
    -- =========================================================
    reference_type TEXT,

    reference_id INTEGER,

    -- =========================================================
    -- Read State
    -- =========================================================
    is_read BOOLEAN NOT NULL DEFAULT FALSE,

    -- =========================================================
    -- Timestamp
    -- =========================================================
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- =========================================================
    -- Relationship
    -- =========================================================
    CONSTRAINT fk_notifications_user
        FOREIGN KEY (user_id)
        REFERENCES users(id)
        ON DELETE CASCADE,

    -- =========================================================
    -- Notification Type Validation
    -- =========================================================
    CONSTRAINT notifications_type_check
        CHECK (
            notification_type IN (
                'order',
                'payment',
                'marketplace',
                'message',
                'training',
                'event',
                'announcement',
                'system'
            )
        ),

    -- =========================================================
    -- Content Validation
    -- =========================================================
    CONSTRAINT notifications_title_nonblank
        CHECK (BTRIM(title) <> ''),

    CONSTRAINT notifications_message_nonblank
        CHECK (BTRIM(message) <> ''),

    -- =========================================================
    -- Reference Validation
    --
    -- A reference type without an ID is incomplete.
    -- An ID without a reference type is also incomplete.
    -- =========================================================
    CONSTRAINT notifications_reference_check
        CHECK (
            (
                reference_type IS NULL
                AND reference_id IS NULL
            )
            OR
            (
                reference_type IS NOT NULL
                AND BTRIM(reference_type) <> ''
                AND reference_id IS NOT NULL
                AND reference_id > 0
            )
        )
);


-- =============================================================
-- NOTIFICATION INDEXES
-- =============================================================

CREATE INDEX IF NOT EXISTS idx_notifications_user_id
ON notifications(user_id);

CREATE INDEX IF NOT EXISTS idx_notifications_created_at
ON notifications(created_at);

CREATE INDEX IF NOT EXISTS idx_notifications_type
ON notifications(notification_type);

CREATE INDEX IF NOT EXISTS idx_notifications_reference
ON notifications(reference_type, reference_id);


-- =============================================================
-- USER NOTIFICATION INBOX
--
-- Optimized for the common query:
--
--   "Show this user's unread notifications, newest first."
-- =============================================================

CREATE INDEX IF NOT EXISTS idx_notifications_user_unread
ON notifications(user_id, is_read, created_at DESC);